# =====================================================================
#  petcare.map - phishing phrases for pet businesses: dog and cat
#  training, grooming, boarding, pet sitting, breeders, shelters,
#  pet shops and veterinary clinics
#  Part of: phywall by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake client complaints (dog injured / bitten / lost during
#           training or boarding) with photo or video "evidence",
#           fake vaccination / vet records to download, fake pet
#           shipping and transport fees (crate, insurance, quarantine),
#           puppy / kitten sale scams, microchip registration renewal,
#           pet insurance claims, booking platform account suspension
#           (Rover, Wag, PetBacker), business page violation notices
#
#  Avoided: normal client questions ("how much is puppy training",
#           "my dog pulls on the leash", "can I book a session"),
#           because real owners write them every day.
# =====================================================================

# ===== English =====
# Fake complaints with "evidence"
/(my|our)\s+(dog|puppy|cat|kitten|pet)\s+(was|got|has\s+been)\s+(injured|hurt|bitten|attacked|abused|lost)\s+(during|at|in)\s+(the\s+|your\s+)?(training|class|session|grooming|boarding|daycare|stay|facility)/i
/(complaint|report)\s+(regarding|about)\s+(the\s+)?(treatment|injury|abuse|neglect)\s+of\s+(my|a|our)\s+(dog|puppy|cat|kitten|pet)/i
/(see|view|check|review)\s+(the\s+)?(photos?|pictures?|videos?|footage|vet\s+report)\s+of\s+(my|the)\s+(dog|puppy|cat|kitten|pet)('s)?\s*(injur|wound|condition)?/i
/(animal\s+cruelty|animal\s+abuse|animal\s+neglect)\s+(report|complaint|case)\s+(has\s+been\s+)?(filed|submitted|opened)\s+against\s+(your|the)\s+(business|facility|company)/i
/(i\s+will|we\s+will)\s+(report|sue|take\s+legal\s+action\s+against)\s+(you|your\s+(business|facility))\s+(for|because\s+of)\s+(what\s+happened\s+to\s+)?(my|our)\s+(dog|cat|pet)/i
# Vet / vaccination records
/(download|view|open|access)\s+(the\s+|your\s+)?(pet'?s?\s+)?(vaccination|vaccine|rabies|medical|vet(erinary)?)\s+(records?|certificates?|history|report)\s+(here|below|via\s+(the\s+)?link|online)/i
/(vaccination|rabies|health)\s+certificate\s+(for\s+(your|the)\s+(dog|puppy|cat|kitten|pet)\s+)?(is\s+)?(expired|invalid|pending|on\s+hold|required\s+to\s+(release|ship))/i
# Pet shipping / transport scams
/(pet|animal|puppy|kitten|dog|cat)\s+(delivery|shipping|transport|relocation)\s+(agency|company|service)\b[^.]{0,60}(fee|payment|charge|insurance|crate)/i
/(refundable|temporary|mandatory)\s+(insurance|crate|cage|quarantine|vaccination)\s+(fee|deposit|payment)[^.]{0,40}(puppy|kitten|pet|dog|cat|animal)/i
/(puppy|kitten|pet|dog|cat|animal)[^.]{0,40}(is\s+)?(held|stuck|detained|on\s+hold)\s+(at|in)\s+(the\s+)?(airport|customs|quarantine|cargo|transit)/i
/(pay|send)\s+(the\s+)?(quarantine|customs|clearance|air\s+ticket|crate)\s+(fee|charge|payment)\s+(to\s+release|before\s+delivery|for\s+(your|the))\s+(puppy|kitten|pet|dog|cat)/i
/(track|tracking)\s+(your\s+)?(puppy|kitten|pet|dog|cat)('s)?\s+(delivery|shipment|transport|flight)\s+(here|online|via)/i
# Puppy / kitten sale scams
/(adorable|healthy|vaccinated|akc\s+registered|purebred)\s+(puppies|kittens|puppy|kitten)\s+(available\s+)?(for\s+(free\s+)?adoption|for\s+re-?homing)[^.]{0,40}(shipping|delivery|transport)\s+fee/i
/(adoption|rehoming|reservation)\s+(fee|deposit)\s+(via|by|through)\s+(zelle|cash\s*app|paypal\s+friends|western\s+union|moneygram|gift\s+cards?|bitcoin|crypto)/i
# Microchip registration
/(your\s+)?(pet'?s?\s+)?microchip\s+(registration|record|database\s+entry|subscription)\s+(has\s+|will\s+)?(expired?|expire|lapsed|be\s+deactivated|be\s+removed)/i
/(renew|update|verify|confirm)\s+(your\s+)?(pet'?s?\s+)?microchip\s+(registration|details|record|subscription)\s+(now|today|online|to\s+(avoid|keep|ensure))/i
/(lost|found)\s+(pet|dog|cat)\s+[^.]{0,30}microchip\s+(scan|lookup)[^.]{0,30}(confirm|verify|pay|claim)/i
# Pet insurance
/(your\s+)?pet\s+insurance\s+(claim|policy|premium|payment)\s+(has\s+been\s+|was\s+)?(rejected|declined|denied|suspended|cancelled|failed)/i
/(pet\s+insurance\s+)?(claim|reimbursement)\s+(for\s+(your|the)\s+(dog|cat|pet)\s+)?(is\s+)?(ready|approved|pending)[^.]{0,30}(verify|confirm|update)\s+(your\s+)?(bank|payment|card)/i
# Booking platforms / business accounts
/(rover|wag|petbacker|pawshake|care\.com|time\s+to\s+pet|gingr|petexec|moego)\s+(account|profile|listing|payouts?)\s+(has\s+been\s+|will\s+be\s+|is\s+)?(suspended|deactivated|restricted|on\s+hold|locked|closed)/i
/(sitter|walker|trainer|groomer|provider)\s+(account|profile)\s+(verification|review)\s+(required|failed|pending)[^.]{0,40}(log\s*in|sign\s*in|verify|confirm)/i
/(your\s+)?(payout|earnings|booking\s+payment)\s+(for\s+(your\s+)?(dog|cat|pet)\s+(sitting|walking|training|boarding)\s+)?(is\s+)?(on\s+hold|pending\s+verification|blocked)/i
/(your\s+)?(business\s+)?(page|profile|account)[^.]{0,30}(violat(es|ed|ion)|reported\s+for)[^.]{0,30}(animal\s+(welfare|cruelty)|selling\s+(live\s+)?animals|pet\s+sales)/i

